from itertools import combinations
S={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# candidates shapes squares and L tromino placements
shapes=[]
for r in range(7):
 for c in range(7):
  sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if sq<=S: shapes.append(('sq',sq))
  for missing in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   tri={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}-{missing}
   if tri<=S: shapes.append(('L',tri))
sol=[]
def search(rem, pieces):
 if not rem:
  sol.append(pieces); return
 cell=min(rem)
 for typ,sh in shapes:
  if cell in sh and sh<=rem:
   search(rem-sh,pieces+[(typ,sh)])
search(S,[])
len(sol)
